namespace Atc.Rest.Api.Generator.Tests.Helpers;

/// <summary>
/// A generated file brings its own usings for the namespaces the SDK's implicit usings would supply, so it compiles in
/// a project with <c>ImplicitUsings</c> off.
/// </summary>
public class ImplicitUsingsHelperTests
{
    private const string AllSeven =
        "using System;\nusing System.Collections.Generic;\nusing System.IO;\nusing System.Linq;\nusing System.Net.Http;\nusing System.Threading;\nusing System.Threading.Tasks;\n";

    [Fact]
    public void AddImplicitUsings_BeforeTheFirstUsing_AfterTheHeader()
    {
        var content = "// <auto-generated />\n#nullable enable\n\nusing System.CodeDom.Compiler;\n\nnamespace Foo;\n";

        var result = ImplicitUsingsHelper.AddImplicitUsings(content);

        Assert.Equal("// <auto-generated />\n#nullable enable\n\n" + AllSeven + "using System.CodeDom.Compiler;\n\nnamespace Foo;\n", result);
    }

    [Fact]
    public void AddImplicitUsings_WithoutUsings_BeforeTheNamespace_WithABlankLine()
    {
        var content = "// <auto-generated />\n#nullable enable\n\nnamespace Foo;\n";

        var result = ImplicitUsingsHelper.AddImplicitUsings(content);

        Assert.Equal("// <auto-generated />\n#nullable enable\n\n" + AllSeven + "\nnamespace Foo;\n", result);
    }

    [Fact]
    public void AddImplicitUsings_SkipsANamespaceTheFileImportsAlready()
    {
        var content = "#nullable enable\nusing System.Linq;\nusing System;\n\nnamespace Foo;\n";

        var result = ImplicitUsingsHelper.AddImplicitUsings(content);

        Assert.Equal(
            "#nullable enable\nusing System.Collections.Generic;\nusing System.IO;\nusing System.Net.Http;\nusing System.Threading;\nusing System.Threading.Tasks;\nusing System.Linq;\nusing System;\n\nnamespace Foo;\n",
            result);
    }

    [Fact]
    public void AddImplicitUsings_AfterGlobalUsings_WhichMustComeFirst()
    {
        var content = "// <auto-generated />\nglobal using System;\nglobal using global::System.Linq;\n\nnamespace Foo;\n";

        var result = ImplicitUsingsHelper.AddImplicitUsings(content);

        Assert.Equal(
            "// <auto-generated />\nglobal using System;\nglobal using global::System.Linq;\n\nusing System.Collections.Generic;\nusing System.IO;\nusing System.Net.Http;\nusing System.Threading;\nusing System.Threading.Tasks;\n\nnamespace Foo;\n",
            result);
    }

    [Fact]
    public void AddImplicitUsings_AFileWithoutCode_StaysAsItIs()
    {
        var content = "// <auto-generated />\n#pragma warning disable CS1591\nglobal using Foo.Handlers;\nglobal using System;";

        Assert.Equal(content, ImplicitUsingsHelper.AddImplicitUsings(content));
    }

    [Fact]
    public void AddImplicitUsings_KeepsTheFilesLineEndings()
    {
        var content = "#nullable enable\r\n\r\nnamespace Foo;\r\n";

        var result = ImplicitUsingsHelper.AddImplicitUsings(content);

        Assert.Equal("#nullable enable\r\n\r\n" + AllSeven.Replace("\n", "\r\n", StringComparison.Ordinal) + "\r\nnamespace Foo;\r\n", result);
    }

    [Fact]
    public void AddImplicitUsings_IsAppliedOnce()
    {
        var once = ImplicitUsingsHelper.AddImplicitUsings("namespace Foo;\n");

        Assert.Equal(once, ImplicitUsingsHelper.AddImplicitUsings(once));
    }

    [Fact]
    public void AddImplicitUsings_AnEmptyFile_StaysEmpty()
        => Assert.Equal(string.Empty, ImplicitUsingsHelper.AddImplicitUsings(string.Empty));
}